UPDATE sys_file SET biz_id = #{instanceId}, remark = JSON_SET(remark, '$.i', #{instanceId})
WHERE tenant_id = #{tenantId} AND deleted = 0 AND biz_type = 'WORKFLOW_FORM' AND access_type = 'PRIVATE'
    AND biz_id = #{definitionId} AND create_by = #{userName}
    AND JSON_UNQUOTE(JSON_EXTRACT(remark, '$.d')) = #{definitionId}
    AND JSON_UNQUOTE(JSON_EXTRACT(remark, '$.f')) = #{fieldPath}
    AND NULLIF(JSON_UNQUOTE(JSON_EXTRACT(remark, '$.i')), 'null') IS NULL
    AND file_id IN #{fileId}
